source('highres_VisiumHD/analysis/hd_mp10_treg_endo_precommunication_v1/code/common.R');gate()
if(file.exists(file.path(root,'tables/reference_holdout_predictions.tsv.gz')) && file.exists(file.path(root,'models/fine_reference.rds')) && file.exists(file.path(root,'models/fine_trained.rds')) && Sys.getenv('HD_RECOMPUTE')!='1')quit(save='no')
m<-rd('reference_membership.tsv.gz');g<-rd('reference_genes.tsv');x<-as(readMM(file.path(root,'temporary/reference.mtx')),'dgCMatrix');rownames(x)<-g$symbol;colnames(x)<-m$cell_id
hd<-rd('hd_genes.tsv');common<-intersect(rownames(x),hd$symbol);common<-setdiff(common,'TIGIT');x<-x[common,];tr<-m$partition=='train';ref<-x[,tr];y<-lognorm(ref)
cat('TRAIN',nrow(ref),ncol(ref),'\n');flush.console();t<-if(file.exists(file.path(root,'models/fine_trained.rds')) && Sys.getenv('HD_RECOMPUTE')!='1')rebuildIndex(readRDS(file.path(root,'models/fine_trained.rds')),num.threads=4) else trainSingleR(y,labels=m$label[tr],genes='de',de.method='wilcox',aggr.ref=TRUE,num.threads=4,BPPARAM=SerialParam());saveRDS(t,file.path(root,'models/fine_trained.rds'));saveRDS(list(counts=ref,metadata=m[tr,],gene_ids='unique approved symbols; count view; TIGIT excluded from classification'),file.path(root,'models/fine_reference.rds'))
put(data.frame(gene=common,selected_singleR=common%in%t$markers$unique),'reference_model_features.tsv');cat('TRAIN_DONE\n');flush.console()
v<-x[,!tr];vm<-m[!tr,];depths<-c(100,300,1000);res<-list()
for(dep in depths){set.seed(123);z<-v;pr<-pmin(1,dep/colSums(z));z@x<-as.numeric(rbinom(length(z@x),round(z@x),rep(pr,diff(z@p))));z<-drop0(z);a<-lognorm(z);used<-t$markers$unique;valid<-colSums(a[used,,drop=FALSE]^2)-colSums(a[used,,drop=FALSE])^2/length(used)>1e-12;ans<-classifySingleR(a[,valid],t,prune=FALSE,num.threads=4,BPPARAM=SerialParam());ans$pruned.labels<-ans$labels;ans$pruned.labels[pruneScores(ans)]<-NA;d<-data.frame(cell_id=vm$cell_id,truth=vm$label,sample=vm$sample,target_depth=dep,actual_UMI=colSums(z),nFeature=colSums(z>0),prediction=NA_character_,pruned=NA_character_);d$prediction[valid]<-ans$labels;d$pruned[valid]<-ans$pruned.labels;res[[as.character(dep)]]<-d;cat('VALIDATED',dep,'\n');flush.console()}
put(do.call(rbind,res),'reference_holdout_predictions.tsv.gz');writeLines(capture.output(sessionInfo()),file.path(root,'logs/sessionInfo_reference.txt'));cat('REFERENCE_COMPLETE\n')
